<script setup lang="ts">
import { ref, computed, watch, onMounted } from 'vue'
import { ArrowUpRight, Check, RefreshCw } from '@lucide/vue'
import { notifyError, state, candidate, confirmedJobs, api, action, refresh, ApiError } from '../store'
import { date, relation, reportSafe } from '../presentation'
import type { RecordData, Job } from '../types'
import ReportView from '../components/ReportView.vue'
import Context from '../components/Context.vue'
import Empty from '../components/Empty.vue'
import QualityPanel from '../components/QualityPanel.vue'
const showQuality = ref(false)
const manualProfile = ref(false); const manual = ref<Job['profile']>({direction:'后端开发',education:null,requirements:[]})
const reports = ref<RecordData[]>([]); const selectedId = ref(''); const reviews = ref<RecordData[]>([]); const status = ref('全部'); const source = ref('existing'); const title = ref('我的目标岗位'); const jd = ref('')
const reviewAction = ref('确认'); const dimension = ref(''); const tier = ref('insufficient'); const reason = ref(''); const rejectChecked = ref(false)
const available = computed(() => reports.value.filter(r => (!state.jobId || r.job_id === state.jobId || (candidate.value && source.value === 'paste')) && (!candidate.value || r.resume_id === state.resumeId) && (status.value === '全部' || r.status === status.value)))
const report = computed(() => available.value.find(r => r.id === selectedId.value) || available.value[0])
let sequence = 0
async function load() { const ticket = ++sequence; try { const r = await api<RecordData[]>(candidate.value ? '/fit/reports' : '/assessments'); if (ticket === sequence) reports.value = r } catch (e) { if (ticket === sequence) notifyError(e) } }
let reviewSequence = 0
watch(() => [report.value?.id, report.value?.status], async ([id]) => { const ticket = ++reviewSequence; reason.value = ''; rejectChecked.value = false; reviews.value = []; dimension.value = report.value?.dimensions[0]?.dimension_id || ''; reviewAction.value = report.value?.status === '已确认' ? '整份打回' : '确认'; if (!id || candidate.value) return; try { const r = await api<RecordData[]>('/reviews?report_id=' + id); if (ticket === reviewSequence) reviews.value = r } catch (e) { if (ticket === reviewSequence) notifyError(e) } })
onMounted(load)
async function analyze() { await action(async () => { let r; try { r = await api('/fit/analyze', 'POST', { resume_id: state.resumeId, ...(source.value === 'paste' ? { title: title.value, jd: jd.value, ...(manualProfile.value ? {manual_profile:manual.value} : {}) } : { job_id: state.jobId }) }) } catch(e) { if (e instanceof ApiError && e.code === 'JD_PARSE_FAILED') manualProfile.value = true; throw e }; if (source.value === 'paste') state.jobId = r.job_id; selectedId.value = r.id; await refresh(); await load() }, '岗位对照已完成，每项结果保留具体岗位参照。') }
async function review() { if (!report.value) return; await action(async () => { await api('/reviews', 'POST', { report_id: report.value!.id, action: reviewAction.value, reason: reason.value, ...(reviewAction.value === '单维改档' ? { dimension_id: dimension.value, tier_after: tier.value } : {}) }); await load(); reviews.value = await api<RecordData[]>('/reviews?report_id=' + report.value!.id); reason.value = '' }, '审阅结果已保存。') }
async function rerun() { await action(async () => { const r = await api('/assessments/' + report.value!.id + '/rerun', 'POST'); if (r.errors.length) throw new Error(r.errors.map((e: RecordData) => e.message).join('；')); await load(); selectedId.value = r.reports[0]?.id || '' }, '报告已重新生成，请再次审阅。') }
</script>
<template>
  <div class="page-heading"><p class="eyebrow">{{ candidate ? '求职空间 / 具体岗位参照' : '招聘工作台 / 第三步' }}</p><h1>{{ candidate ? '我的岗位对照' : '能力报告与审阅' }}</h1><p>{{ candidate ? '把经历与目标岗位放在一起，看清相符之处和可补充的依据。' : '先看证据，再作判断。人工确认后，报告才进入比较。' }}</p></div>
  <form v-if="candidate" class="surface analyze-form" @submit.prevent="analyze"><div class="fit-method-row"><div class="fit-methods" role="group" aria-label="目标岗位来源"><button type="button" :aria-pressed="source === 'existing'" :class="{ active: source === 'existing' }" @click="source = 'existing'">选择已提供岗位</button><button type="button" :aria-pressed="source === 'paste'" :class="{ active: source === 'paste' }" @click="source = 'paste'">粘贴目标 JD</button></div><span>选择参照，再开始对照</span></div><div class="fit-setup"><Context with-resume :hide-job="source === 'paste'"><button v-if="source === 'existing'" class="primary" :disabled="state.busy || !state.jobId || !state.resumeId">开始岗位对照<ArrowUpRight :size="17" /></button></Context><div v-if="!state.resumes.length || (source === 'existing' && !confirmedJobs.length)" class="fit-readiness"><p>{{ !state.resumes.length ? '还没有可用的简历，导入后即可开始岗位对照。' : '还没有已确认的参照岗位，可以先查看岗位，或切换到粘贴目标 JD。' }}</p><RouterLink v-if="!state.resumes.length" to="/resumes" class="secondary button">导入简历<ArrowUpRight :size="15" /></RouterLink><RouterLink v-else to="/jobs" class="secondary button">查看岗位<ArrowUpRight :size="15" /></RouterLink></div></div><div v-if="source === 'paste'" class="detail-body"><label>目标岗位名称<input v-model="title" required minlength="2" maxlength="100"></label><label>完整目标 JD<textarea v-model="jd" rows="6" required minlength="20" maxlength="30000" placeholder="粘贴想了解的岗位描述。" /></label><label class="check"><input v-model="manualProfile" type="checkbox">手工确认岗位画像（解析失败时可使用）</label><section v-if="manualProfile" class="form-section"><p class="muted">填写岗位明确写出的要求，每项引用须来自上方 JD。此参照仅保存到你的账号。</p><div class="form-grid"><label>技术方向<input v-model="manual.direction" required /></label><label>学历要求<select v-model="manual.education"><option :value="null">未指定</option><option v-for="degree in ['大专','本科','硕士','博士']" :key="degree">{{ degree }}</option></select></label></div><article v-for="(r,i) in manual.requirements" :key="i" class="requirement-card"><div class="form-grid"><label>技能<input v-model="r.skill" required maxlength="100" /></label><label>要求的行为等级<select v-model.number="r.required_level"><option v-for="n in 4" :key="n" :value="n">{{ n }} 级</option></select></label></div><label>对应 JD 原文<textarea v-model="r.quote" required rows="2" /></label><label class="check"><input v-model="r.hard" type="checkbox">主要要求</label><button type="button" class="text-link" @click="manual.requirements.splice(i,1)">移除此项</button></article><button type="button" class="secondary" @click="manual.requirements.push({skill:'',required_level:2,quote:'',hard:true})">添加技能要求</button></section><button class="primary" :disabled="state.busy || !state.resumeId">开始岗位对照<ArrowUpRight :size="17" /></button></div></form>
  <Context v-else><button type="button" class="secondary" @click="showQuality = !showQuality">{{ showQuality ? '收起质量看板' : '材料与审阅质量' }}</button><label>报告状态<select v-model="status"><option v-for="s in ['全部','待确认','已确认','已打回']" :key="s">{{ s }}</option></select></label><button class="secondary" @click="action(load)" :disabled="state.busy"><RefreshCw :size="15" />刷新报告</button></Context>
  <QualityPanel v-if="!candidate && showQuality" :job-id="state.jobId" />
  <Empty v-if="!available.length" title="还没有这一岗位的报告" :text="candidate ? '选择具体岗位或粘贴目标 JD，开始对照。' : '在简历与初筛中选择材料，生成能力报告。'" :to="candidate ? undefined : '/resumes'" label="选择简历" />
  <div v-else class="report-layout"><aside class="surface report-list"><div class="list-toolbar"><h3>{{ candidate ? '对照记录' : '分析记录' }}</h3><small>{{ available.length }} 份 · 保留历史版本</small></div><button v-for="r in available" :key="r.id" :class="['select-row', { selected: r.id === report?.id }]" @click="selectedId = r.id" :disabled="state.busy"><span class="row-main"><strong>{{ r.display_name }}</strong><span>{{ r.job_title }}</span><small>{{ date(r.created_at) }}</small></span><span v-if="!candidate" class="pill">{{ r.status }}</span></button></aside>
    <section v-if="report" class="report-content surface"><div v-if="!candidate && reportSafe(report, state.presentation!, false)" class="review-toolbar"><span>当前状态：<strong>{{ report.status }}</strong></span><a href="#review" class="button primary">前往人工审阅 ↓</a></div><ReportView :report="report" :candidate="candidate" /><template v-if="!candidate && reportSafe(report, state.presentation!, false)"><section class="review-panel" id="review"><div class="section-heading"><h3>人工审阅</h3><span class="pill">{{ report.status }}</span></div><div v-if="report.status === '已打回'"><p>该记录保留历史依据。重新生成后，审阅新报告。</p><button class="primary" @click="rerun" :disabled="state.busy"><RefreshCw :size="16" />重新生成报告</button></div><form v-else @submit.prevent="review"><div class="form-grid"><label>审阅操作<select v-model="reviewAction"><option v-if="report.status !== '已确认'" value="确认">确认报告</option><option v-if="report.status !== '已确认'" value="单维改档">修改单项关系</option><option value="整份打回">整份打回</option></select></label><label v-if="reviewAction === '单维改档'">修改维度<select v-model="dimension"><option v-for="d in report.dimensions" :key="d.dimension_id" :value="d.dimension_id">{{ d.name }}</option></select></label><label v-if="reviewAction === '单维改档'">新的相对要求关系<select v-model="tier"><option v-for="(label, t) in state.presentation!.tier_labels" :key="t" :value="t">{{ label }}</option></select></label></div><label>审阅理由<textarea v-model="reason" required minlength="2" maxlength="1000" rows="3" placeholder="记录判断的原文依据，便于日后回溯。" /></label><label v-if="reviewAction === '整份打回'" class="check"><input v-model="rejectChecked" type="checkbox">确认打回，后续需重新分析</label><div class="form-footer"><span>{{ report.status === '已确认' ? '已确认报告锁定，修改须先打回。' : '缺少原文的维度不能改为明确关系。' }}</span><button class="primary" :disabled="state.busy || reason.trim().length < 2 || (reviewAction === '整份打回' && !rejectChecked)"><Check :size="16" />保存审阅结果</button></div></form><button v-if="report.status === '已确认'" class="secondary" :disabled="state.busy" @click="action(async () => { await api('/assessments/' + report!.id + '/followups', 'POST'); await load() }, '面试追问已生成，可在面试准备中查看。')">生成面试追问</button><details class="evidence-detail"><summary>审阅记录 · {{ reviews.length }} 条</summary><div class="evidence-body"><article v-for="r in reviews" :key="r.id"><strong>{{ r.action === '单维改档' ? '修改单项关系' : r.action }}</strong><p>{{ r.reason }}</p><small>{{ date(r.created_at) }}</small></article><p v-if="!reviews.length" class="muted">尚未进行人工审阅。</p></div></details></section></template></section>
  </div>
</template>

<style scoped>
.analyze-form.surface{border:1px solid var(--border-soft);border-radius:14px;background:var(--surface-paper);overflow:hidden}
.fit-method-row{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:20px 24px;border-bottom:1px solid var(--border-soft);background:var(--surface-paper)}
.fit-method-row>span{font-size:12px;color:var(--text-muted)}
.fit-methods{display:inline-flex;gap:5px;padding:5px;border:1px solid var(--border-soft);background:var(--brand-faint);border-radius:10px;max-width:100%}
.fit-methods>button{min-height:37px;padding:7px 16px;border:1px solid transparent;border-radius:7px;background:transparent;color:var(--text-muted);font-size:12px;line-height:1.6;white-space:nowrap}
.fit-methods>button:hover{background:var(--brand-soft);color:var(--brand-ink)}
.fit-methods>button[aria-pressed=true]{background:var(--brand);color:var(--brand-on);border-color:var(--brand);box-shadow:0 1px 3px var(--button-shadow);font-weight:600}
.fit-setup{padding:24px;background:var(--surface-paper)}
.analyze-form .fit-setup :deep(.context-bar){display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;align-items:end;gap:20px;border:0;border-radius:0;margin:0;padding:0;background:transparent;box-shadow:none}
.analyze-form .fit-setup :deep(.context-bar label){min-width:0;width:auto;margin:0;display:flex;flex-direction:column;gap:9px;font-size:12px;font-weight:600;color:var(--text-main)}
.analyze-form .fit-setup :deep(.context-bar select){width:100%;min-width:0;min-height:44px;background:var(--surface-paper);font-weight:400}
.analyze-form .fit-setup :deep(.context-bar>.primary){min-height:44px;margin-bottom:3px;padding:10px 20px;white-space:nowrap}
.fit-readiness{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-top:22px;padding:15px 17px;background:var(--brand-faint);border:1px solid var(--border-soft);border-radius:9px}
.fit-readiness p{margin:0;font-size:12px;line-height:1.8;color:var(--text-muted)}
.fit-readiness .button{font-size:12px;flex-shrink:0;min-height:36px}
.analyze-form>.detail-body{padding:0 24px 26px}
@media(max-width:800px){.analyze-form .fit-setup :deep(.context-bar){grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.analyze-form .fit-setup :deep(.context-bar>.primary){grid-column:1/-1;justify-self:start}.fit-method-row>span{display:none}}
@media(max-width:520px){.fit-method-row{padding:16px}.fit-setup{padding:20px 16px}.analyze-form .fit-setup :deep(.context-bar){grid-template-columns:minmax(0,1fr);gap:18px}.fit-readiness{align-items:flex-start;flex-direction:column;gap:12px}.fit-methods{width:100%}.fit-methods>button{flex:1;padding:7px 10px}.analyze-form>.detail-body{padding:0 16px 20px}}
</style>
